insert into public.resources (title, description, category, url, tags, uploaded_by, created_at) values
  ('Damodaran Online — the full valuation course', 'Aswath Damodaran''s entire NYU Stern valuation class: slides, lecture videos, spreadsheets and the industry datasets he updates every January. If you only bookmark one finance site, this is it.', 'Academics', 'https://pages.stern.nyu.edu/~adamodar/', ARRAY['valuation', 'corporate finance', 'NYU Stern']::text[], NULL, '2026-07-15T00:00:00.000Z'),
  ('Damodaran''s updated industry datasets', 'Betas, cost of capital, margins and multiples by sector and geography — the numbers you cite when a professor asks where your WACC came from.', 'Finance', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/data.html', ARRAY['data', 'WACC', 'valuation']::text[], NULL, '2026-07-17T00:00:00.000Z'),
  ('MIT OCW — Finance Theory I (15.401)', 'Full lecture notes and problem sets covering NPV, portfolio theory, CAPM and capital structure. Maps almost one-to-one onto our Term 1 corporate finance syllabus.', 'Academics', 'https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/', ARRAY['academics', 'corporate finance', 'MIT']::text[], NULL, '2026-07-18T00:00:00.000Z'),
  ('MIT OCW — Marketing Management (15.810)', 'Segmentation, positioning, pricing and channel strategy with the case list. Good companion reading before marketing management sessions.', 'Marketing', 'https://ocw.mit.edu/courses/15-810-marketing-management-fall-2015/', ARRAY['academics', 'marketing', 'MIT']::text[], NULL, '2026-07-19T00:00:00.000Z'),
  ('MIT OCW — full management course catalogue', 'Every Sloan course MIT has published: operations, system dynamics, organisational processes, entrepreneurship. Free lecture notes for anything you are behind on.', 'Academics', 'https://ocw.mit.edu/search/?d=Sloan%20School%20of%20Management', ARRAY['academics', 'operations', 'MIT']::text[], NULL, '2026-07-20T00:00:00.000Z'),
  ('NPTEL — management course library', 'IIT/IISc video courses in management, operations research and economics. Useful when you want the same topic explained a second way, in an Indian context.', 'Academics', 'https://nptel.ac.in/course.html', ARRAY['academics', 'India', 'lectures']::text[], NULL, '2026-07-21T00:00:00.000Z'),
  ('Term 1 Corporate Finance — consolidated cohort notes', 'Chapter-wise notes with solved past-paper questions: capital structure, WACC, dividend policy, and the formula sheet the seniors circulated.', 'Academics', 'https://drive.google.com/drive/folders/cohort-first-corpfin', ARRAY['academics', 'finance', 'notes']::text[], NULL, '2026-08-17T00:00:00.000Z'),
  ('Statistics & econometrics refresher — Khan Academy', 'If regression output still feels like magic, this is the fastest way to fix it before the quant methods midterm.', 'Analytics', 'https://www.khanacademy.org/math/statistics-probability', ARRAY['statistics', 'regression', 'basics']::text[], NULL, '2026-07-23T00:00:00.000Z'),
  ('Wall Street Prep — free finance knowledge base', 'Hundreds of short explainers on accounting, LBO mechanics, comps and precedent transactions. The de facto glossary for finance recruiting.', 'Finance', 'https://www.wallstreetprep.com/knowledge/', ARRAY['IB', 'modelling', 'accounting']::text[], NULL, '2026-07-24T00:00:00.000Z'),
  ('Macabacus — modelling and Excel best practice', 'How bankers actually format and structure models: circularity, toggles, keyboard shortcuts and the shortcuts that pay for themselves in week one.', 'Finance', 'https://macabacus.com/learn', ARRAY['Excel', 'modelling', 'formatting']::text[], NULL, '2026-07-25T00:00:00.000Z'),
  ('A Simple Model — free financial modelling course', 'Builds a three-statement model from a blank sheet across short videos, with downloadable Excel files at every stage.', 'Finance', 'https://www.asimplemodel.com/', ARRAY['modelling', 'Excel', 'three-statement']::text[], NULL, '2026-07-26T00:00:00.000Z'),
  ('Corporate Finance Institute — free course collection', 'CFI''s free tier covers accounting fundamentals, Excel, and an intro to valuation. Certificates are optional; the templates are the real value.', 'Courses', 'https://corporatefinanceinstitute.com/collections/', ARRAY['courses', 'finance', 'Excel']::text[], NULL, '2026-07-27T00:00:00.000Z'),
  ('Three-statement model template (cohort build)', 'Clean Excel template with linked IS/BS/CF, a working-capital schedule and a debt waterfall. Comments explain every driver so you can defend it in an interview.', 'Finance', 'https://drive.google.com/drive/folders/cohort-first-3sm', ARRAY['modelling', 'Excel', 'valuation']::text[], NULL, '2026-07-31T00:00:00.000Z'),
  ('Zerodha Varsity — markets, from zero', 'The best free Indian markets curriculum: equities, futures, options, and a genuinely good module on reading annual reports.', 'Finance', 'https://zerodha.com/varsity/', ARRAY['India', 'markets', 'equities']::text[], NULL, '2026-07-28T00:00:00.000Z'),
  ('Investopedia financial dictionary', 'When a term shows up in a case and you have ninety seconds to understand it before you speak.', 'Finance', 'https://www.investopedia.com/financial-term-dictionary-4769738', ARRAY['glossary', 'basics']::text[], NULL, '2026-07-29T00:00:00.000Z'),
  ('Aswath Damodaran on YouTube', 'Full valuation and corporate finance lectures, plus his running commentary on live deals and market bubbles. Watch at 1.5x.', 'Finance', 'https://www.youtube.com/@AswathDamodaranonValuation', ARRAY['valuation', 'lectures', 'video']::text[], NULL, '2026-07-30T00:00:00.000Z'),
