  ('Mergers & Inquisitions — finance recruiting bible', 'Brutally honest guides to IB, PE and HF recruiting: what the job is, what the interview asks, and what the exit actually looks like.', 'Interview Prep', 'https://www.mergersandinquisitions.com/', ARRAY['IB', 'recruiting', 'careers']::text[], NULL, '2026-07-31T00:00:00.000Z'),
  ('Investment banking technical question bank', 'The 120-question technical set we drilled: accounting, enterprise value, DCF, LBO and merger maths, with worked answers.', 'Interview Prep', 'https://drive.google.com/drive/folders/cohort-first-ib-guide', ARRAY['IB', 'interviews', 'technicals']::text[], NULL, '2026-07-27T00:00:00.000Z'),
  ('PrepLounge case library', 'Hundreds of user-submitted and firm-published cases with a partner-matching tool so you always have someone to practise with.', 'Interview Prep', 'https://www.preplounge.com/en/case-interview', ARRAY['consulting', 'cases', 'practice']::text[], NULL, '2026-08-01T00:00:00.000Z'),
  ('Victor Cheng — Case Interview Secrets', 'The classic frameworks-and-structure resource. Skim the free videos, then steal the issue-tree habit and drop the rigid frameworks.', 'Interview Prep', 'https://www.caseinterview.com/', ARRAY['consulting', 'cases', 'frameworks']::text[], NULL, '2026-08-02T00:00:00.000Z'),
