  ('McKinsey — official interview prep', 'How the firm describes its own process, plus the Solve assessment and sample cases. Read this before any mock.', 'Interview Prep', 'https://www.mckinsey.com/careers/interviewing', ARRAY['MBB', 'consulting', 'interviews']::text[], NULL, '2026-08-03T00:00:00.000Z'),
  ('BCG — interview preparation hub', 'Sample cases, the online chatbot case, and BCG''s own guidance on what a strong structure looks like.', 'Interview Prep', 'https://www.bcg.com/careers/interview-prep', ARRAY['MBB', 'consulting', 'interviews']::text[], NULL, '2026-08-04T00:00:00.000Z'),
  ('Bain — case interview practice', 'Bain''s practice cases with written walkthroughs, including the classic Coffee Shop Co. warm-up.', 'Interview Prep', 'https://www.bain.com/careers/interview-prep/case-interview/', ARRAY['MBB', 'consulting', 'cases']::text[], NULL, '2026-08-04T00:00:00.000Z'),
