  ('Bain Insights', 'Bain''s reports, including the annual Global Private Equity Report and the India luxury/consumer studies.', 'Consulting', 'https://www.bain.com/insights/', ARRAY['research', 'PE', 'consumer']::text[], NULL, '2026-08-07T00:00:00.000Z'),
  ('think-cell tutorials', 'How consultants build waterfall, Marimekko and Gantt charts fast. Even without the licence, the chart grammar is worth learning.', 'Consulting', 'https://www.think-cell.com/en/resources/tutorials', ARRAY['decks', 'charts', 'PowerPoint']::text[], NULL, '2026-08-08T00:00:00.000Z'),
