  ('Stratechery archive', 'Ben Thompson on platform strategy and aggregation theory. The clearest writing anywhere on why tech businesses win.', 'Strategy', 'https://stratechery.com/', ARRAY['tech strategy', 'platforms', 'writing']::text[], NULL, '2026-08-09T00:00:00.000Z'),
