  ('Harvard Business Publishing Education', 'Where the cases we''re assigned come from. Student pricing, and the free preview pages are often enough for context.', 'Case Studies', 'https://hbsp.harvard.edu/home/', ARRAY['cases', 'HBS', 'academics']::text[], NULL, '2026-08-11T00:00:00.000Z'),
