  ('Seth Godin''s blog', 'A decade of short posts on positioning and permission marketing. Read ten at random; at least three will change how you write.', 'Marketing', 'https://seths.blog/', ARRAY['marketing', 'positioning', 'writing']::text[], NULL, '2026-08-11T00:00:00.000Z'),
  ('Reforge blog — growth frameworks', 'Retention, growth loops and monetisation frameworks written by operators. Strong for anyone recruiting into growth or D2C.', 'Marketing', 'https://www.reforge.com/blog', ARRAY['growth', 'retention', 'loops']::text[], NULL, '2026-08-12T00:00:00.000Z'),
  ('Brand positioning workshop template', 'The one-page positioning canvas we used at P&G, plus two filled-in examples for a launch and a relaunch.', 'Marketing', 'https://drive.google.com/drive/folders/cohort-first-positioning', ARRAY['brand', 'positioning', 'template']::text[], NULL, '2026-08-13T00:00:00.000Z'),
