  ('Mode — the SQL tutorial', 'From SELECT to window functions with a live query editor on real datasets. Two evenings gets you interview-ready SQL.', 'Analytics', 'https://mode.com/sql-tutorial/', ARRAY['SQL', 'data', 'analytics']::text[], NULL, '2026-08-13T00:00:00.000Z'),
