  ('Route-efficiency dashboard — worked example', 'Cohort project files: the SQL, the model and the Power BI dashboard from a real logistics ops problem.', 'Operations', 'https://github.com/cohort-first/route-efficiency', ARRAY['SQL', 'dashboards', 'logistics']::text[], NULL, '2026-08-21T00:00:00.000Z'),
  ('Lenny''s Newsletter', 'The default reading for product people: growth, PM career paths, and hiring loops at real companies.', 'Product', 'https://www.lennysnewsletter.com/', ARRAY['product', 'growth', 'careers']::text[], NULL, '2026-08-15T00:00:00.000Z'),
  ('SVPG — Marty Cagan''s articles', 'Product discovery, empowered teams, and why feature factories fail. Read ''Product vs Feature Teams'' first.', 'Product', 'https://www.svpg.com/articles/', ARRAY['product', 'discovery', 'teams']::text[], NULL, '2026-08-16T00:00:00.000Z'),
