  ('How to read an AI paper (and what to skip)', 'A short cohort guide to getting through AI research quickly — what matters in the method section and what is usually noise.', 'AI', 'https://drive.google.com/drive/folders/cohort-first-ai-papers', ARRAY['AI', 'research', 'learning']::text[], NULL, '2026-08-06T00:00:00.000Z'),
  ('Y Combinator Startup School', 'Free, structured curriculum on going from idea to launch, with the library of YC founder talks attached.', 'Entrepreneurship', 'https://www.startupschool.org/', ARRAY['startups', 'founders', 'YC']::text[], NULL, '2026-08-19T00:00:00.000Z'),
  ('Paul Graham''s essays', 'Twenty years of writing on startups, ideas and doing ambitious work. Start with ''Do Things That Don''t Scale''.', 'Entrepreneurship', 'https://paulgraham.com/articles.html', ARRAY['startups', 'essays', 'writing']::text[], NULL, '2026-08-19T00:00:00.000Z'),
  ('Sequoia — writing a business plan', 'The pitch deck outline most Indian seed investors still expect, straight from the source.', 'Entrepreneurship', 'https://www.sequoiacap.com/article/writing-a-business-plan/', ARRAY['fundraising', 'pitch deck', 'VC']::text[], NULL, '2026-08-20T00:00:00.000Z'),
  ('First Round Review', 'Long-form operator interviews on hiring, pricing and scaling. Closest thing to a free operating manual.', 'Entrepreneurship', 'https://review.firstround.com/', ARRAY['startups', 'operations', 'hiring']::text[], NULL, '2026-08-20T00:00:00.000Z'),
  ('a16z — insights and podcasts', 'Sector theses on AI, fintech and consumer. Useful for framing why a market is interesting in a VC interview.', 'Entrepreneurship', 'https://a16z.com/', ARRAY['VC', 'theses', 'tech']::text[], NULL, '2026-08-20T00:00:00.000Z'),
  ('Seed fundraising: deck, data room, diligence', 'What actually goes into a seed raise — the deck that worked, the data-room folder tree, and the questions investors asked.', 'Entrepreneurship', 'https://drive.google.com/drive/folders/cohort-first-seed-raise', ARRAY['fundraising', 'startups', 'VC']::text[], NULL, '2026-08-12T00:00:00.000Z'),
  ('Term sheet vocabulary in plain English', 'Liquidation preference, pro-rata, ratchets and ESOP maths explained without legalese, with worked numbers.', 'Entrepreneurship', 'https://drive.google.com/drive/folders/cohort-first-term-sheets', ARRAY['VC', 'term sheets', 'startups']::text[], NULL, '2026-08-14T00:00:00.000Z'),
  ('Levels.fyi — compensation data', 'Real, verified pay bands by company, level and city. Use it before you negotiate anything.', 'Career', 'https://www.levels.fyi/', ARRAY['compensation', 'negotiation', 'careers']::text[], NULL, '2026-08-21T00:00:00.000Z'),
  ('Ask a Manager', 'Twenty years of workplace questions answered well. Unreasonably useful for internships and first-job politics.', 'Career', 'https://www.askamanager.org/', ARRAY['workplace', 'careers', 'advice']::text[], NULL, '2026-08-21T00:00:00.000Z'),
  ('Finshots — three-minute business news', 'Daily Indian business explainers. The cheapest way to sound informed in a networking call.', 'Career', 'https://finshots.in/', ARRAY['India', 'news', 'business']::text[], NULL, '2026-08-22T00:00:00.000Z'),
  ('The Ken', 'Long-form Indian business journalism. One story a day, properly reported — good for industry prep on Indian firms.', 'Career', 'https://the-ken.com/', ARRAY['India', 'journalism', 'industry']::text[], NULL, '2026-08-22T00:00:00.000Z'),
