  ('CV and cover letter clinic — cohort templates', 'Two CV templates (finance and consulting), the bullet formula that survived MBB screening, and ten before/after rewrites.', 'Career', 'https://drive.google.com/drive/folders/cohort-first-cv-clinic', ARRAY['CV', 'career', 'templates']::text[], NULL, '2026-08-23T00:00:00.000Z'),
  ('Free courses worth actually finishing', 'A curated shortlist — SQL, statistics, negotiation and design — with hours required and what each is genuinely good for.', 'Courses', 'https://drive.google.com/drive/folders/cohort-first-course-shortlist', ARRAY['courses', 'learning', 'career']::text[], NULL, '2026-08-20T00:00:00.000Z'),
  ('Wharton Business Foundations (Coursera)', 'Wharton''s core MBA sequence — accounting, marketing, operations, finance — auditable free. Good for filling a weak core.', 'Courses', 'https://www.coursera.org/specializations/wharton-business-foundations', ARRAY['courses', 'core', 'Wharton']::text[], NULL, '2026-08-19T00:00:00.000Z'),
  ('The Personal MBA — reading list', 'Josh Kaufman''s list of the business books that are actually worth the hours, ranked and summarised.', 'Books', 'https://personalmba.com/best-business-books/', ARRAY['books', 'reading list']::text[], NULL, '2026-08-23T00:00:00.000Z'),
  ('Thinking, Fast and Slow', 'Kahneman on judgement under uncertainty. Shows up in behavioural finance, marketing and negotiation alike.', 'Books', 'https://www.goodreads.com/book/show/11468377-thinking-fast-and-slow', ARRAY['books', 'behavioural', 'decisions']::text[], NULL, '2026-08-23T00:00:00.000Z'),
  ('The Goal — Goldratt', 'A novel about a factory that teaches the theory of constraints better than any ops textbook. Read it before the operations core.', 'Books', 'https://www.goodreads.com/book/show/113934.The_Goal', ARRAY['books', 'operations', 'constraints']::text[], NULL, '2026-08-24T00:00:00.000Z'),
  ('Competitive Strategy — Porter', 'The source text behind half our strategy syllabus. Skim the first four chapters and you''ll follow every session.', 'Books', 'https://www.goodreads.com/book/show/40646.Competitive_Strategy', ARRAY['books', 'strategy', 'Porter']::text[], NULL, '2026-08-24T00:00:00.000Z'),
  ('Zero to One — Thiel', 'Contrarian, arguable and short. Useful as a foil in any entrepreneurship discussion.', 'Books', 'https://www.goodreads.com/book/show/18050143-zero-to-one', ARRAY['books', 'startups', 'strategy']::text[], NULL, '2026-08-24T00:00:00.000Z');
